  async function compress(file,type){const bitmap=await createImageBitmap(file),max=type==='MAP'?4096:1600,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),w=Math.max(1,Math.round(bitmap.width*scale)),h=Math.max(1,Math.round(bitmap.height*scale)),surface=document.createElement('canvas');surface.width=w;surface.height=h;surface.getContext('2d').drawImage(bitmap,0,0,w,h);bitmap.close();const mime=file.type==='image/png'?'image/png':'image/webp';return {src:surface.toDataURL(mime,mime==='image/png'?undefined:.84),width:w,height:h};}
  function offerImport(files,x,y,local=false){const rect=viewport.getBoundingClientRect(),clientX=local?rect.left+x:x,clientY=local?rect.top+y:y;pendingImport={files:[...files].filter(file=>file.type.startsWith('image/')),point:screenToWorld(clientX,clientY),screen:{x:clientX-rect.left,y:clientY-rect.top}};}
  async function confirmImport(type){if(!pendingImport)return;const pending=pendingImport;pendingImport=null;importType=type;await importFiles(pending.files,pending.point,type);}
  async function importFiles(files,point={x:0,y:0},type=importType){status='Optimisation des images…';for(const file of files){if(!file.type.startsWith('image/'))continue;try{const image=await compress(file,type),isCharacter=type==='CHARACTER',span=isCharacter?table.grid.size:type==='MAP'?Math.min(1400,Math.max(600,image.width/1.8)):Math.min(700,Math.max(180,image.width/3)),ratio=image.height/image.width,item={id:uid(),name:file.name.replace(/\.[^.]+$/,''),type,src:image.src,x:point.x,y:point.y,w:span,h:isCharacter?span:span*ratio,rotation:0,opacity:1,locked:type==='MAP',hidden:false,round:isCharacter&&tokenCrop,showName:false,rings:[]};commit(()=>{table.items=[...table.items,item].sort((a,b)=>layerRank[a.type]-layerRank[b.type])});const loaded=new Image();loaded.onload=draw;loaded.src=item.src;images.set(item.id,loaded);selected=item.id;selectedIds=[item.id];}catch(error){status=`Import impossible : ${error.message}`;}}status='Images importées et compressées';}
  async function createCharacter(){const portrait=sheet?.portrait||sheet?.identity?.portrait||sheet?.identity?.image||sheet?.image;if(!portrait||!/^data:image|^https?:|^blob:|^\//.test(portrait)){status='Ajoutez d’abord une image principale au personnage.';return;}const item={id:uid(),name:sheet.identity?.nom||'Personnage',type:'CHARACTER',src:portrait,x:-table.camera.x,y:-table.camera.y,w:table.grid.size,h:table.grid.size,rotation:0,opacity:1,locked:false,hidden:false,round:true,showName:false,rings:[]};commit(()=>table.items=[...table.items,item].sort((a,b)=>layerRank[a.type]-layerRank[b.type]));const image=new Image();image.onload=draw;image.onerror=()=>status='Le portrait du personnage n’a pas pu être chargé.';image.src=item.src;images.set(item.id,image);selected=item.id;selectedIds=[item.id];status=`Token de ${item.name} placé au centre`;}
  function updateSelected(patch){const ids=selectedIds.length?selectedIds:[selected];commit(()=>table.items=table.items.map(item=>ids.includes(item.id)?{...item,...patch}:item));}
  function removeSelected(){const ids=selectedIds.length?selectedIds:[selected];commit(()=>table.items=table.items.filter(item=>!ids.includes(item.id)));for(const id of ids)images.delete(id);selected='';selectedIds=[];}
  function duplicateItem(item,offset=20){const copy={...clone(item),id:uid(),name:`${item.name} (copie)`,x:item.x+offset,y:item.y+offset,locked:false};commit(()=>table.items=[...table.items,copy].sort((a,b)=>layerRank[a.type]-layerRank[b.type]));if(copy.src){const image=new Image();image.onload=draw;image.src=copy.src;images.set(copy.id,image);}selected=copy.id;selectedIds=[copy.id];return copy;}
  function duplicateSelection(offset=20){const source=selectedItems(),copies=source.map(item=>({...clone(item),id:uid(),name:`${item.name} (copie)`,x:item.x+offset,y:item.y+offset,locked:false}));commit(()=>table.items=[...table.items,...copies].sort((a,b)=>layerRank[a.type]-layerRank[b.type]));for(const copy of copies)if(copy.src){const image=new Image();image.onload=draw;image.src=copy.src;images.set(copy.id,image);}selectedIds=copies.map(copy=>copy.id);selected=selectedIds.at(-1)||'';return copies.find(copy=>copy.type===source.find(item=>item.id===selected)?.type)||copies.at(-1);}
  function duplicate(){selectedIds.length>1?duplicateSelection():duplicateItem(table.items.find(item=>item.id===selected));}
  function placeAsset(item,point={x:-table.camera.x,y:-table.camera.y}){const copy={...clone(item),id:uid(),x:point.x,y:point.y,locked:item.type==='MAP',hidden:false};commit(()=>table.items=[...table.items,copy]);const image=new Image();image.onload=draw;image.src=copy.src;images.set(copy.id,image);selected=copy.id;selectedIds=[copy.id];}
  function dropStage(event){event.preventDefault();const assetId=event.dataTransfer.getData('text/vtt-asset'),point=screenToWorld(event.clientX,event.clientY);if(assetId){const item=table.items.find(candidate=>candidate.id===assetId);if(item)placeAsset(item,point);return;}offerImport([...event.dataTransfer.files],event.clientX,event.clientY);}
  function beginTransform(event,kind){event.stopPropagation();const items=selectedItems(),item=table.items.find(item=>item.id===selected);if(!item||!items.length)return;const before=clone(table),bounds=selectionBounds(),origins=Object.fromEntries(items.map(value=>[value.id,clone(value)])),start=screenToWorld(event.clientX,event.clientY),startDistance=Math.max(1,Math.hypot(start.x-bounds.x,start.y-bounds.y)),ratio=item.w/item.h;event.currentTarget.setPointerCapture(event.pointerId);const move=e=>{const point=screenToWorld(e.clientX,e.clientY);if(kind==='rotate'&&items.length===1){updateDirect({rotation:Math.atan2(point.y-item.y,point.x-item.x)*180/Math.PI+90});}else{const scale=Math.max(.1,Math.hypot(point.x-bounds.x,point.y-bounds.y)/startDistance);table.items=table.items.map(value=>{const origin=origins[value.id];return origin?{...value,x:bounds.x+(origin.x-bounds.x)*scale,y:bounds.y+(origin.y-bounds.y)*scale,w:Math.max(4,origin.w*scale),h:Math.max(4,origin.h*scale)}:value});table={...table};}};const end=e=>{e.currentTarget.removeEventListener('pointermove',move);e.currentTarget.removeEventListener('pointerup',end);history.push(before);if(history.length>50)history.shift();future=[];};event.currentTarget.addEventListener('pointermove',move);event.currentTarget.addEventListener('pointerup',end);}
  function updateDirect(patch){table.items=table.items.map(item=>item.id===selected?{...item,...patch}:item);table={...table};}
  function toggleRing(color){const item=table.items.find(item=>item.id===selected);if(!item)return;const rings=item.rings||[],next=rings.includes(color)?rings.filter(value=>value!==color):[...rings,color];updateSelected({rings:next});}
  function changeLayer(id,type){const ids=id===selected&&selectedIds.length?selectedIds:[id];commit(()=>table.items=table.items.map(item=>ids.includes(item.id)?{...item,type}:item).sort((a,b)=>layerRank[a.type]-layerRank[b.type]));layerMenu=false;}
  function reorderNear(sourceId,targetId){if(!sourceId||sourceId===targetId)return;commit(()=>{const items=[...table.items],from=items.findIndex(i=>i.id===sourceId),to=items.findIndex(i=>i.id===targetId);if(from<0||to<0)return;const [item]=items.splice(from,1);items.splice(to,0,item);table.items=items;});}
  function raiseInCategory(id){const items=[...table.items],index=items.findIndex(item=>item.id===id);if(index<0)return;const [item]=items.splice(index,1);let target=-1;items.forEach((other,i)=>{if(other.type===item.type)target=i});items.splice(target+1,0,item);table.items=items;table={...table};}
  function focusItem(item){selected=item.id;selectedIds=[item.id];const from={x:table.camera.x,y:table.camera.y},to={x:-item.x,y:-item.y},started=performance.now(),duration=280;const animate=now=>{const t=Math.min(1,(now-started)/duration),ease=1-Math.pow(1-t,3);table.camera.x=from.x+(to.x-from.x)*ease;table.camera.y=from.y+(to.y-from.y)*ease;draw();if(t<1)requestAnimationFrame(animate);else table={...table};};requestAnimationFrame(animate);}
  function rename(id,name){const value=name.trim();if(value)commit(()=>table.items=table.items.map(item=>item.id===id?{...item,name:value}:item));editingName='';editingOutliner='';}
  function saveTextDraft(value){const text=value.trim(),draft=textDraft;textDraft=null;if(!text||!draft)return;const item={id:uid(),kind:'drawing',shape:'text',type:'NOTE',name:text,x:draft.x,y:draft.y,w:Math.max(110,text.length*15),h:36,fontSize:24,color:'#111',hidden:false,locked:false,showName:false};commit(()=>table.items=[...table.items,item].sort((a,b)=>layerRank[a.type]-layerRank[b.type]));selected=item.id;selectedIds=[item.id];}
  function chooseMeasure(kind){measureTool=kind;tool=kind;measure=null;measureMenu=false;}
  async function exportScene(){const blob=new Blob([JSON.stringify(table,null,2)],{type:'application/json'}),name=`cardenveil-scene-${new Date().toISOString().slice(0,10)}.json`;try{if(window.showSaveFilePicker){const handle=await window.showSaveFilePicker({suggestedName:name,types:[{description:'Scène Cardenveil',accept:{'application/json':['.json']}}]}),stream=await handle.createWritable();await stream.write(blob);await stream.close();status='Scène enregistrée dans le fichier choisi';return;}}catch(error){if(error.name==='AbortError')return;}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status='Scène exportée';}
  async function importScene(file){try{const parsed=JSON.parse(await file.text()),next=normalizeTable(parsed);history.push(clone(table));table=next;images.clear();hydrate();selected='';selectedIds=[];status='Scène importée';}catch(error){status=`Fichier de scène invalide : ${error.message}`;}finally{sceneInput.value='';}}
  function keydown(event){if(['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;if(event.key==='Delete'&&selected)removeSelected();else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();duplicate();}}
</script>

<section class:full class:map-focused={mapFocused} class="vtt-shell surface" aria-label="Table virtuelle Cardenveil">
  <header class="vtt-header"><div class="vtt-header-actions"><button onclick={createCharacter}>Créer le personnage</button><button onclick={chooseStorageFolder} title="Choisir le stockage de la scène">{folderName?`Stockage : ${folderName}`:'Stockage local'}</button><button onclick={exportScene}>Exporter</button><button onclick={()=>sceneInput.click()}>Importer</button><input bind:this={sceneInput} hidden type="file" accept="application/json,.json" onchange={e=>e.currentTarget.files[0]&&importScene(e.currentTarget.files[0])}><button onclick={openMapWindow} title="Ouvrir la map dans un nouvel onglet">Nouvel onglet</button><button class:full-exit={full} onclick={()=>full=!full} aria-label={full?'Quitter le plein écran':'Passer en plein écran'} title={full?'Quitter le plein écran':'Plein écran'}><VttIcon name={full?'minimize':'maximize'} size={17}/></button></div></header>
  <div class="vtt-workspace">
    <aside class="vtt-tools" aria-label="Outils">
      <button class:active={tool==='select'} onclick={()=>{tool='select';measure=null}} title="Sélectionner"><VttIcon name="cursor"/></button>
      <button class:active={tool==='pan'} onclick={()=>{tool='pan';measure=null}} title="Déplacer la vue et les tokens"><VttIcon name="hand"/></button>
      <div class="vtt-tool-group"><button class:active={['measure','range','moveMeasure'].includes(tool)} onclick={()=>chooseMeasure(measureTool)} oncontextmenu={e=>{e.preventDefault();measureMenu=!measureMenu}} title="Outil de mesure — clic droit pour choisir"><VttIcon name={measureTool==='range'?'range':measureTool==='moveMeasure'?'move':'measure'}/></button><button class="tool-caret" onclick={()=>measureMenu=!measureMenu} aria-label="Choisir le type de mesure">›</button>{#if measureMenu}<div class="measure-menu"><button class:active={measureTool==='measure'} onclick={()=>chooseMeasure('measure')}><VttIcon name="measure"/><span>Distance euclidienne</span></button><button class:active={measureTool==='range'} onclick={()=>chooseMeasure('range')}><VttIcon name="range"/><span>Portées Cardenveil</span></button><button class:active={measureTool==='moveMeasure'} onclick={()=>chooseMeasure('moveMeasure')}><VttIcon name="move"/><span>Déplacement mesuré</span></button></div>{/if}</div>
      <div class="vtt-tool-group"><button class:active={['brush','line','rect','ellipse','erase'].includes(tool)} onclick={()=>tool=drawMode} oncontextmenu={e=>{e.preventDefault();drawMenu=!drawMenu}} title="Dessiner — clic droit pour choisir"><VttIcon name={drawMode}/></button><button class="tool-caret" onclick={()=>drawMenu=!drawMenu} aria-label="Choisir le dessin">›</button>{#if drawMenu}<div class="measure-menu draw-menu">{#each [['brush','Crayon'],['line','Ligne'],['rect','Rectangle'],['ellipse','Cercle'],['erase','Gomme']] as [key,label]}<button class:active={drawMode===key} onclick={()=>{drawMode=key;tool=key;drawMenu=false}}><VttIcon name={key}/><span>{label}</span></button>{/each}<div class="draw-colors" aria-label="Couleur du dessin">{#each ['#111111','#ffffff','#6d6d6d','#795548','#d32f2f','#ec407a','#f57c00','#fbc02d','#7cb342','#388e3c','#00897b','#00acc1','#1976d2','#3949ab','#7b1fa2','#8e24aa'] as color}<button class:active={drawColor===color} style={`--draw-color:${color}`} onclick={()=>drawColor=color} aria-label={`Couleur ${color}`}></button>{/each}<input type="color" bind:value={drawColor} title="Couleur personnalisée"></div><label class="draw-opacity">Transparence <input type="range" min="0.1" max="1" step="0.05" bind:value={drawOpacity}><span>{Math.round(drawOpacity*100)}%</span></label></div>{/if}</div>
      <button class:active={tool==='text'} onclick={()=>tool='text'} title="Ajouter un texte"><VttIcon name="text"/></button>
      <button class:active={settings} onclick={()=>settings=!settings} title="Grille"><VttIcon name="grid"/></button><button disabled={!history.length} onclick={undo} title="Annuler"><VttIcon name="undo"/></button><button disabled={!future.length} onclick={redo} title="Rétablir"><VttIcon name="redo"/></button>
    </aside>
    <div class="vtt-stage" bind:this={viewport} tabindex="0" role="application" aria-label="Scène, utilisez la molette pour zoomer" oncontextmenu={e=>e.preventDefault()} onkeydown={keydown} ondragover={e=>e.preventDefault()} ondrop={dropStage}>
      <canvas bind:this={canvas} onpointerdown={pointerDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={pointerUp} onwheel={wheel} ondblclick={canvasDoubleClick}></canvas>
      {#if textDraft}<input class="vtt-inline-text" style={`left:${textDraft.screen.x}px;top:${textDraft.screen.y}px`} placeholder="Écrivez votre texte…" onkeydown={e=>{if(e.key==='Enter')saveTextDraft(e.currentTarget.value);if(e.key==='Escape')textDraft=null}} onblur={e=>saveTextDraft(e.currentTarget.value)} autofocus>{/if}
      {#if settings}<div class="vtt-popover grid-settings"><strong>Grille carrée</strong><label><input type="checkbox" bind:checked={table.grid.visible}> Afficher</label><label><input type="checkbox" bind:checked={table.grid.snap}> Aimantation au déplacement</label><label>Taille<input type="range" min="24" max="160" bind:value={table.grid.size}></label><label>Échelle<input type="number" min="0.01" step="0.5" bind:value={table.grid.scale}></label><label>Unité<input maxlength="6" bind:value={table.grid.unit}></label><label>Opacité<input type="range" min="0" max="1" step=".05" bind:value={table.grid.opacity}></label></div>{/if}
      <button class="outliner-toggle-right" class:active={outliner} onclick={()=>outliner=!outliner} title={outliner?'Fermer l’outliner':'Ouvrir l’outliner'}><VttIcon name={outliner?'chevron-right':'chevron-left'}/></button>
      {#if selected}<div class:has-name={table.items.find(i=>i.id===selected)?.showName} class="vtt-token-overlay" style={selectedOverlay()}><button class="rotate" onpointerdown={e=>beginTransform(e,'rotate')} title="Tourner">↻</button><button class="resize left" onpointerdown={e=>beginTransform(e,'resize')} title="Redimensionner">↔</button><button class="resize right" onpointerdown={e=>beginTransform(e,'resize')} title="Redimensionner">↔</button>{#if table.items.find(i=>i.id===selected)?.showName}{#if editingName===selected}<input class="vtt-token-name editing" value={table.items.find(i=>i.id===selected)?.name} onkeydown={e=>{if(e.key==='Enter')rename(selected,e.currentTarget.value);if(e.key==='Escape')editingName=''}} onblur={e=>rename(selected,e.currentTarget.value)} autofocus>{:else}<button class="vtt-token-name" ondblclick={()=>editingName=selected} onclick={()=>editingName=selected} title="Cliquer pour renommer">{table.items.find(i=>i.id===selected)?.name}</button>{/if}{/if}<div class="vtt-selection-menu"><button class:active={table.items.find(i=>i.id===selected)?.hidden} onclick={()=>updateSelected({hidden:!table.items.find(i=>i.id===selected)?.hidden})} title={table.items.find(i=>i.id===selected)?.hidden?'Réafficher':'Masquer'}><VttIcon name={table.items.find(i=>i.id===selected)?.hidden?'eye-off':'eye'}/></button><button class:active={table.items.find(i=>i.id===selected)?.locked} onclick={()=>updateSelected({locked:!table.items.find(i=>i.id===selected)?.locked})} title="Verrouiller"><VttIcon name={table.items.find(i=>i.id===selected)?.locked?'lock':'unlock'}/></button><button class:active={layerMenu} onclick={()=>layerMenu=!layerMenu} title="Changer de calque"><VttIcon name="layers"/></button><button class:active={ringsOpen} onclick={()=>ringsOpen=!ringsOpen} title="Anneaux colorés"><VttIcon name="range"/></button><button onclick={duplicate} title="Dupliquer"><VttIcon name="copy"/></button><button class:active={table.items.find(i=>i.id===selected)?.showName} onclick={()=>updateSelected({showName:!table.items.find(i=>i.id===selected)?.showName})} title="Afficher le nom"><VttIcon name="text"/></button><button onclick={removeSelected} title="Supprimer"><VttIcon name="trash"/></button></div>{#if layerMenu}<div class="vtt-layer-picker">{#each IMAGE_TYPES as [key,label]}<button class:active={table.items.find(i=>i.id===selected)?.type===key} onclick={()=>changeLayer(selected,key)} title={label}><VttIcon name={key.toLowerCase()}/><span>{label}</span></button>{/each}</div>{/if}{#if ringsOpen}<div class="vtt-rings">{#each ['#e53935','#fb8c00','#fdd835','#43a047','#00acc1','#1e88e5','#5e35b1','#d81b60','#ffffff','#111111'] as color}<button style={`--ring:${color}`} class:active={table.items.find(i=>i.id===selected)?.rings?.includes(color)} onclick={()=>toggleRing(color)} aria-label={`Anneau ${color}`}></button>{/each}</div>{/if}</div>{/if}
      {#if pendingImport}<div class="vtt-import-wheel" style={`left:${pendingImport.screen.x}px;top:${pendingImport.screen.y}px`}><div><small>Importer comme</small><strong>{IMPORT_TYPES.find(([key])=>key===importType)?.[1]}</strong></div>{#each IMPORT_TYPES as [key,label],index}<button style={`--wheel-index:${index}`} class:active={importType===key} onmouseenter={()=>importType=key} onclick={()=>confirmImport(key)} title={label}><VttIcon name={key.toLowerCase()} size={24}/></button>{/each}<button class="wheel-cancel" onclick={()=>pendingImport=null} title="Annuler" aria-label="Annuler">×</button></div>{/if}
      <div class="vtt-assets" class:open={assetTray}><div class="vtt-asset-items">{#if assetTray}{#each table.items.filter((item,index,list)=>item.type===assetTray&&item.src&&list.findIndex(other=>other.src===item.src)===index) as item}<button draggable="true" ondragstart={e=>{e.dataTransfer.setData('text/vtt-asset',item.id);e.dataTransfer.effectAllowed='copy'}} onclick={()=>placeAsset(item)} title={`Glisser ou cliquer pour placer ${item.name}`}><img src={item.src} alt=""><span>{item.name}</span></button>{:else}<p>Importez votre première image dans cette catégorie.</p>{/each}<button class="asset-add" onclick={()=>fileInput.click()} title="Importer dans cette catégorie"><VttIcon name="add" size={20}/></button>{/if}</div><div class="vtt-asset-tabs">{#each IMPORT_TYPES as [key,label]}<button class:active={assetTray===key} onclick={()=>{importType=key;assetTray=assetTray===key?'':key}} title={label}><VttIcon name={key.toLowerCase()} size={18}/></button>{/each}<button onclick={()=>{importType=assetTray||'PROP';fileInput.click()}} title="Importer"><VttIcon name="add" size={18}/></button></div>{#if assetTray==='CHARACTER'}<label class="round-option"><input type="checkbox" bind:checked={tokenCrop}> Token rond à l’import</label>{/if}<input bind:this={fileInput} hidden type="file" accept="image/*" multiple onchange={e=>{importFiles([...e.currentTarget.files],{x:-table.camera.x,y:-table.camera.y},importType);e.currentTarget.value=''}}></div>
    </div>
    {#if outliner}<aside class="vtt-outliner"><div><strong>Outliner</strong><span>{table.items.length}</span></div>{#each [...IMAGE_TYPES].reverse() as [key,label]}<details open ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();changeLayer(e.dataTransfer.getData('text/item-id'),key)}}><summary>{label}</summary>{#each [...table.items].reverse().filter(i=>i.type===key) as item}<div class:selected={selectedIds.includes(item.id)} class="outliner-row" draggable={editingOutliner!==item.id} ondragstart={e=>e.dataTransfer.setData('text/item-id',item.id)} ondragover={e=>e.preventDefault()} ondrop={e=>{e.stopPropagation();e.preventDefault();reorderNear(e.dataTransfer.getData('text/item-id'),item.id)}}>{#if editingOutliner===item.id}<input class="outliner-name-input" value={item.name} onkeydown={e=>{if(e.key==='Enter')rename(item.id,e.currentTarget.value);if(e.key==='Escape')editingOutliner=''}} onblur={e=>rename(item.id,e.currentTarget.value)} autofocus>{:else}<button class="item-name" onclick={e=>{if(e.shiftKey){selectedIds=selectedIds.includes(item.id)?selectedIds.filter(id=>id!==item.id):[...selectedIds,item.id];selected=selectedIds.at(-1)||'';}else{selected=item.id;selectedIds=[item.id];}draw()}} ondblclick={()=>focusItem(item)} title="Double-clic : centrer"><span class="drag-grip">⠿</span><span ondblclick={e=>{e.stopPropagation();editingOutliner=item.id}} title="Double-cliquer pour renommer">{item.name}</span></button>{/if}<button class="outliner-action" title={item.hidden?'Afficher':'Masquer'} onmousedown={()=>{selected=item.id;selectedIds=[item.id]}} onclick={()=>updateSelected({hidden:!item.hidden})}><VttIcon name={item.hidden?'eye-off':'eye'} size={15}/></button><button class="outliner-action" title={item.locked?'Déverrouiller':'Verrouiller'} onmousedown={()=>{selected=item.id;selectedIds=[item.id]}} onclick={()=>updateSelected({locked:!item.locked})}><VttIcon name={item.locked?'lock':'unlock'} size={15}/></button></div>{/each}</details>{/each}</aside>{/if}
  </div>
</section>
